def cards(items):
    return '<div class="card-grid">'+''.join(f'''<article class="service-card reveal"><img src="{img}" alt="{html.escape(alt)}"><div><p class="eyebrow">{ey}</p><h3>{title}</h3><p>{text}</p><a href="{url}">Δείτε λεπτομέρειες</a></div></article>''' for title,ey,text,img,url,alt in items)+'</div>'

